<section class="page-banner"><div class="container"><span class="eyebrow">OUR PRODUCTS</span><h1>Product catalogue.</h1><p>Explore oils and lubricants by category, name or application.</p></div></section><section class="section container"><form class="catalogue-filters" action="<?= url('products') ?>"><div><label for="search">Search products</label><input id="search" type="search" name="q" value="<?= e($q) ?>" placeholder="Product name, category or application"></div><div><label for="category">Product category</label><select name="category" id="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $category==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">Search ↗</button><a class="btn" href="<?= url('products') ?>">Reset</a></form><div class="results-line"><span><?= $total ?> <?= $total===1?'product':'products' ?><?= $q?' for “'.e($q).'”':'' ?></span><span>PRODUCT CATALOGUE</span></div><div class="product-grid"><?php foreach($products as $product) require BASE_PATH.'/app/Views/partials/product-card.php'; ?><?php if(!$products): ?><div class="empty"><h3>No products found.</h3><p>Try a different keyword or select another category.</p><a class="text-link" href="<?= url('products') ?>">Browse all products ↗</a></div><?php endif; ?></div><?php if($pages>1): ?><nav class="pagination" aria-label="Catalogue pages"><?php for($i=1;$i<=$pages;$i++): ?><a <?= $page===$i?'aria-current="page"':'' ?> href="<?= e(url('products?'.http_build_query(['q'=>$q,'category'=>$category,'page'=>$i]))) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?></section>
